  await expect(proposal.line(2).locator('.line-tax')).toHaveText('109.68');
  await expect(proposal.line(3).locator('.line-tax')).toHaveText('2,632.37');

  // Rounding the unrounded sum instead would give 11,183.25.
  await expect(proposal.subtotal).toHaveText('11,183.26');
  await expect(proposal.tax).toHaveText('2,851.73');
  await expect(proposal.total).toHaveText('14,034.99 SEK');

  page.once('dialog', (dialog) => dialog.accept());
  await page.locator('#delete-proposal').click();
